(() => {
const form = document.getElementById('commentform');
if (!form) return;
const ta = document.getElementById('comment');
const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
const grow = () => { if (!ta) return; ta.style.height = 'auto'; ta.style.height = Math.min(ta.scrollHeight + 2, 480) + 'px'; };
if (ta) ta.addEventListener('input', grow);
document.addEventListener('click', e => {
const link = e.target.closest && e.target.closest('.comment-reply-link, #cancel-comment-reply-link');
if (!link) return;
setTimeout(() => {
const respond = document.getElementById('respond'); if (!respond) return;
const r = respond.getBoundingClientRect();
if (r.top < 0 || r.bottom > innerHeight) respond.scrollIntoView({ behavior: reduce ? 'auto' : 'smooth', block: 'center' });
if (ta && link.classList.contains('comment-reply-link')) ta.focus({ preventScroll: true });
}, 0);
});
const reg = document.getElementById('meeha_register'), email = document.getElementById('email');
if (reg && email) {
const req = email.required;
reg.addEventListener('change', () => { email.required = reg.checked || req; });
}
form.addEventListener('submit', () => {
const btn = form.querySelector('.m-cmt__submit'); if (!btn) return;
setTimeout(() => { btn.disabled = true; btn.value = 'পোস্ট হচ্ছে…'; }, 0);
});
addEventListener('pageshow', () => {
const btn = form.querySelector('.m-cmt__submit');
if (btn && btn.disabled) { btn.disabled = false; btn.value = 'মন্তব্য পোস্ট করুন'; }
});
})();
;
